import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { parseCheckpoint } from '../src/engine/loader';
import { forward, createRunBuffers } from '../src/engine/forward';
import { HookRegistry } from '../src/engine/hooks';

// Golden reference generated by Karpathy's run.c (llama2.c) compiled at -O3,
// dumping raw (pre-softmax) logits for prompt "Once upon a time".
interface RefLogit {
  id: number;
  logit: number;
}
interface RefStep {
  pos: number;
  fed_token: number;
  top10: RefLogit[];
  argmax: number;
}
interface Fixture {
  prompt: string;
  prompt_tokens: number[];
  vocab_size: number;
  steps: RefStep[];
}

// Measured max delta vs run.c is ~1.1e-5 (float32 accumulation-order noise);
// 5e-5 gives 4x headroom while still catching any real numerical bug.
const TOLERANCE = 5e-5;

const fixture: Fixture = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), 'tests/fixtures/reference-logits.json'), 'utf8')
);

const ckptBuf = fs.readFileSync(path.join(process.cwd(), 'public/models/stories15M.bin'));
const ckptArray = ckptBuf.buffer.slice(ckptBuf.byteOffset, ckptBuf.byteOffset + ckptBuf.byteLength);
const { config, weights } = parseCheckpoint(ckptArray);
const buffers = createRunBuffers(config);
const hooks = new HookRegistry();

describe('golden fixture: forward pass vs llama2.c run.c reference', () => {
  it('prompt tokenization matches the reference', () => {
    expect(fixture.prompt).toBe('Once upon a time');
    expect(fixture.prompt_tokens).toEqual([1, 9038, 2501, 263, 931]);
  });

  it('logits match the C reference within 5e-5 at every position', () => {
    const divergences: string[] = [];

    for (const step of fixture.steps) {
      const logits = forward(step.fed_token, step.pos, config, weights, buffers, hooks);
      const data = logits.data;

      // Our argmax must equal the reference argmax — catches rank-flipped bugs
      // even when magnitudes happen to be close.
      let ourArgmax = 0;
      for (let j = 1; j < config.vocabSize; j++) {
        if (data[logits.offset + j] > data[logits.offset + ourArgmax]) ourArgmax = j;
      }

      if (ourArgmax !== step.argmax) {
        divergences.push(
          `pos ${step.pos} (fed ${step.fed_token}): argmax mismatch — ` +
            `ref=${step.argmax} (${step.top10[0].logit}), ours=${ourArgmax} (${data[logits.offset + ourArgmax]})`
        );
      }

      // Compare raw logit magnitudes on the reference top-10 ids
      for (const ref of step.top10) {
        const ours = data[logits.offset + ref.id];
        const delta = Math.abs(ours - ref.logit);
        if (delta > TOLERANCE) {
          divergences.push(
            `pos ${step.pos} (fed ${step.fed_token}): token ${ref.id} ` +
              `ref=${ref.logit} ours=${ours.toFixed(6)} Δ=${delta.toExponential(3)}`
          );
        }
      }
    }

    if (divergences.length > 0) {
      const first = divergences[0];
      throw new Error(
        `Forward pass diverges from run.c reference (${divergences.length} mismatches).\n` +
          `First divergence: ${first}\n` +
          divergences.slice(0, 15).join('\n')
      );
    }
  });
});
